{"summary": "Implemented first_Element to return the first element within the first n entries occurring exactly k times (or -1 if none) and added tests for that behavior.", "files": {"solution.py": """"Write a python function to find the first element occurring k times in a given array."""


def first_Element(arr, n, k):
    """Return the first element in ``arr[:n]`` occurring exactly ``k`` times.

    Return ``-1`` if no such element exists, if ``k`` is not
    positive, or if the considered portion of the array is empty.
    """
    if not arr or n <= 0 or k <= 0:
        return -1

    elements = arr[:n]

    counts = {}
    for value in elements:
        counts[value] = counts.get(value, 0) + 1

    for value in elements:
        if counts[value] == k:
            return value

    return -1
